mapper.select:
SELECT c.id AS contract_id, c.ends_on AS due_date
FROM employee_contract c
WHERE c.renewal_status = 'NOT_DUE'
  AND c.ends_on >= #{today}
  AND c.ends_on <= #{through}
ORDER BY c.ends_on ASC, c.id ASC

SELECT EXISTS (
    SELECT 1 FROM contract_reminder_event e
    WHERE e.contract_id = #{contractId} AND e.reminder_stage = #{stage}
)

mapper.update:
UPDATE contract_reminder_event
SET status = 'ACKED', acked_at = #{ackedAt}
WHERE id = #{id} AND status = 'PENDING'
